import{_ as r,o as n,c as a,a3 as t,j as e,a as i}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/vorbereitung/pruefung-restabschnitte.jpg",l="/bilder/vorbereitung/gp-abschlussdatum-berechnen.jpg",o="/bilder/vorbereitung/abschlussdatum-in-individualdaten-i.jpg",f=JSON.parse('{"title":"Das voraussichtliche Abschlussdatum neu berechnen","description":"","frontmatter":{"title":"Das voraussichtliche Abschlussdatum neu berechnen","source_pageid":385,"source_revision":5328},"headers":[],"relativePath":"zeugnisse/vorbereitung/abschlussdatum-neu-berechnen-gruppenprozesse-allgemein.md","filePath":"zeugnisse/vorbereitung/abschlussdatum-neu-berechnen-gruppenprozesse-allgemein.md"}'),c={name:"zeugnisse/vorbereitung/abschlussdatum-neu-berechnen-gruppenprozesse-allgemein.md"};function h(d,s,p,b,g,m){return n(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="das-voraussichtliche-abschlussdatum-neu-berechnen" tabindex="-1">Das voraussichtliche Abschlussdatum neu berechnen <a class="header-anchor" href="#das-voraussichtliche-abschlussdatum-neu-berechnen" aria-label="Permalink to &quot;Das voraussichtliche Abschlussdatum neu berechnen&quot;">​</a></h1><p>Berechnen Sie das Abschlussdatum aus den im Jahrgangskatalog hinterlegten Restabschnitten. Prüfen Sie diese Angaben vor dem Start des Gruppenprozesses.</p><p><a href="/bilder/vorbereitung/pruefung-restabschnitte.jpg"><img src="'+u+'" alt="Prüfung korrekte Restabschnittanzahl" loading="lazy"></a></p><p><em>Prüfung korrekte Restabschnittanzahl</em></p><p>Dieser Gruppenprozess realisiert das automatisierte Berechnen des Abschlussdatums.</p><p>Damit diese Berechnung korrekt funktioniert, müssen bei den <em>Statistik-Jahrgängen</em>, die über Reiter <em>&quot;Kataloge ➜ Schulbezogene Kataloge&quot;</em> zu finden sind, die Restabschnitte, also die Anzahl der noch zu absolvierenden Halbjahre oder Quartale bis zum höchsten erreichbaren Abschluss, korrekt eingetragen sein.</p><p><a href="/bilder/vorbereitung/gp-abschlussdatum-berechnen.jpg"><img src="'+l+'" alt="Ausführen des Gruppenprozesses" loading="lazy"></a></p><p><em>Ausführen des Gruppenprozesses</em></p><p>Sind die Einträge korrekt, kann der entsprechende Gruppenprozess angestoßen werden.</p><p><a href="/bilder/vorbereitung/abschlussdatum-in-individualdaten-i.jpg"><img src="'+o+'" alt="Anzeige des errechneten Abschlussdatums" loading="lazy"></a></p><p><em>Anzeige des errechneten Abschlussdatums</em></p><p>Nach diesem Gruppenprozess steht das neu berechnete Abschlussdatum auf der Registerkarte unter Individualdaten I.</p><hr><p><strong>Videotutorial</strong></p>',14),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/xFFvSDb6HWU?",frameborder:"0",allowfullscreen:""},null,-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Abschlussdatum_neu_berechnen_(Gruppenprozesse_Allgemein)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),i(" · Quellrevision 5328.")],-1)])])}const v=r(c,[["render",h]]);export{f as __pageData,v as default};
